import{_ as p,a0 as l,w as r,s as u,ao as n,I as i,a1 as s,A as o,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"如何安装和使用 Latte Dock | LCTT x X-CMD","titleTemplate":false,"description":"如何安装和使用 Latte Dock | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何安装和使用 Latte Dock | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何安装和使用 Latte Dock | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20211204 How to Install and Use Latte Dock on Ubuntu and Other Linux Distributions","title":"如何安装和使用 Latte Dock","tag":"202203","desc":""},"relativePath":"202203/20211204 How to Install and Use Latte Dock on Ubuntu and Other Linux Distributions.md","filePath":"[post].md"}'),d={name:"202203/20211204 How to Install and Use Latte Dock on Ubuntu and Other Linux Distributions.md"};function b(c,t,k,h,m,g){const e=l("Link");return r(),u("div",null,[t[27]||(t[27]=n('<h1 id="如何安装和使用-latte-dock" tabindex="-1">如何安装和使用 Latte Dock <a class="header-anchor" href="#如何安装和使用-latte-dock" aria-label="Permalink to “如何安装和使用 Latte Dock”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202203/09/091040v3n0vlxvt9a0zokx.jpg" alt=""></p><p>你知道什么是“<ruby>停靠区<rt>Dock</rt></ruby>” 吧，它通常是你的应用程序“停靠”的底栏，以便快速访问。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/latte-dock.webp?resize=800%2C167&amp;ssl=1" alt=""></p><p>许多发行版和桌面环境都提供了某种停靠实现。如果你的发行版没有“<ruby>停靠区<rt>Dock</rt></ruby>”，或者你想尝试一些新的停靠应用，Latte Dock 是一个不错的选择。它类似于 macOS 上的停靠区，每次你用鼠标悬停在任何停靠对象上时，都会有一个的抛物线动画。</p><p>在本教程中，我将告诉你如何在 Ubuntu 上安装 Latte Dock。我还会展示一些关于使用和定制 Latte Dock 的事情。</p><h3 id="在-ubuntu-上安装-latte-dock" tabindex="-1">在 Ubuntu 上安装 Latte Dock <a class="header-anchor" href="#在-ubuntu-上安装-latte-dock" aria-label="Permalink to “在 Ubuntu 上安装 Latte Dock”">​</a></h3>',7)),i("p",null,[s(e,{href:"https://invent.kde.org/plasma/latte-dock"},{default:o(()=>[...t[0]||(t[0]=[a("Latte Dock",-1)])]),_:1}),t[1]||(t[1]=a(" 是一个流行的应用程序，可以从大多数 Linux 发行版的官方软件库中获得。也就是说你可以使用你的发行版的软件中心或软件包管理器来安装 Latte dock。",-1))]),t[28]||(t[28]=n('<p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/latte-ubuntu-software-center.png?resize=800%2C384&amp;ssl=1" alt="Latte 可以从软件中心获得"></p><p>在 Ubuntu 和其他基于 Ubuntu 的发行版，如 elementary OS、Linux Mint、Pop!_OS、Zorin OS 上，使用 <code>apt</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install latte-dock</span></span></code></pre></div><p>这就行了！现在你已经在 Ubuntu 上安装了 Latte Dock。</p><h4 id="停用-ubuntu-自带的停靠区-针对-ubuntu-用户" tabindex="-1">停用 Ubuntu 自带的停靠区（针对 Ubuntu 用户） <a class="header-anchor" href="#停用-ubuntu-自带的停靠区-针对-ubuntu-用户" aria-label="Permalink to “停用 Ubuntu 自带的停靠区（针对 Ubuntu 用户）”">​</a></h4>',5)),i("p",null,[t[3]||(t[3]=a("在你启动你闪亮的新停靠区之前，我建议你禁用 Ubuntu 默认提供的停靠区。这里有一个 ",-1)),s(e,{href:"https://itsfoss.com/disable-ubuntu-dock/"},{default:o(()=>[...t[2]||(t[2]=[a("关于如何禁用 Ubuntu 的停靠区的指南",-1)])]),_:1}),t[4]||(t[4]=a("。",-1))]),t[29]||(t[29]=n('<p>要禁用停靠区，请在你的终端输入以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gnome-extensions disable ubuntu-dock@ubuntu.com</span></span></code></pre></div><p>如果你最终改变了主意，你可以用以下命令再次启用 Ubuntu 停靠区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gnome-extensions enable ubuntu-dock@ubuntu.com</span></span></code></pre></div><blockquote><p>注意：</p><p>这不能禁用 Pop!_OS 20.04 LTS 上的默认停靠区（尽管它在桌面上默认是隐藏的；只在活动概览中可见）。在使用 COSMIC 桌面环境/扩展的 Pop!_OS 上，你可以通过“<ruby>设置<rt>Settings</rt></ruby>”应用中的“<ruby>桌面<rt>Desktop</rt></ruby> -&gt; <ruby>停靠区<rt>Dock</rt></ruby>”来禁用或启用停靠区。</p></blockquote><h3 id="开始使用-latte-dock" tabindex="-1">开始使用 Latte Dock <a class="header-anchor" href="#开始使用-latte-dock" aria-label="Permalink to “开始使用 Latte Dock”">​</a></h3><p>我在教程中使用的是 Pop!_OS，但这些步骤适用于任何 Linux 发行版。</p><p>一旦安装完毕，你会在你的应用程序抽屉里发现一个 Latte Dock 的启动器图标。你可以在这里访问它，或者按 <code>Super</code> 键（通常是 <code>Windows</code> 键；如果你有 Mac 键盘，则按 <code>Command</code> 键）键 + <code>A</code>。</p><p>从这里打开 Latte Dock：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/02_latte_in_drawer.webp?resize=800%2C450&amp;ssl=1" alt="应用抽屉里高亮显示的 Latte dock"></p><p>酷！现在你的桌面上已经打开了 Latte Dock。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/03_latte_dock_launched.webp?resize=800%2C450&amp;ssl=1" alt="桌面上的 Latte Dock 屏幕截图"></p><h4 id="启用-latte-dock-的自动启动功能" tabindex="-1">启用 Latte Dock 的自动启动功能 <a class="header-anchor" href="#启用-latte-dock-的自动启动功能" aria-label="Permalink to “启用 Latte Dock 的自动启动功能”">​</a></h4><p>随着 Latte Dock 的打开，以及 Ubuntu 自带停靠区的禁用，如果你现在重启，那么下次你的电脑开机时就不会有任何停靠区了。</p><p>让我们现在就来解决这个问题。</p><p>在停靠区上点击右键。点击“<ruby>布局<rt>Layouts</rt></ruby>”子菜单下的“<ruby>配置<rt>Configure</rt></ruby>”选项。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/configure-latte-dock.png?resize=800%2C392&amp;ssl=1" alt="通过进入“布局” -&gt; “配置” 启动设置面板窗口"></p><p>现在，在“<ruby>偏好<rt>Preferences</rt></ruby>”选项卡下，确保“<ruby>在启动时启用自动启动<rt>Enable autostart during startup</rt></ruby>”复选框被选中。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/enable_autostart_latte_dock.webp?resize=800%2C433&amp;ssl=1" alt="启用启动时自动启动复选框"></p><h3 id="定制你的停靠区" tabindex="-1">定制你的停靠区 <a class="header-anchor" href="#定制你的停靠区" aria-label="Permalink to “定制你的停靠区”">​</a></h3><p>如果你安装了任何 KDE 的产品，定制应该是永无止境的。如果 Latte Dock 不允许定制，那就奇怪了。幸运的是，情况并非如此。</p><p>你可以做各种各样的事情来定制 Latte Dock。增加它的大小，使它更透明或半透明，为它设计主题等等。</p><h4 id="将应用程序固定在停靠区上" tabindex="-1">将应用程序固定在停靠区上 <a class="header-anchor" href="#将应用程序固定在停靠区上" aria-label="Permalink to “将应用程序固定在停靠区上”">​</a></h4><p>要把你的应用程序固定在 Latte Dock 上，打开该应用程序，右键点击在你停靠区中的应用程序图标。现在点击“<ruby>固定启动器<rt></rt>Pin Launcher</ruby>”。完成了！你的应用程序现在已经被固定到了停靠区上。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/pin-app-latte-dock.webp?resize=800%2C334&amp;ssl=1" alt="右击正在运行的应用程序并选择钉住启动器选项"></p><p>你可以通过点击和拖动移动它到左边或右边来改变它在停靠区中的位置。</p><h4 id="搜索和安装-latte-dock-主题" tabindex="-1">搜索和安装 Latte Dock 主题 <a class="header-anchor" href="#搜索和安装-latte-dock-主题" aria-label="Permalink to “搜索和安装 Latte Dock 主题”">​</a></h4><p>通过右击停靠区打开 Latte Dock 的“<ruby>设置<rt>Settings</rt></ruby>”窗口，点击“<ruby>布局<rt>Layout</rt></ruby>”子菜单下的“<ruby>配置<rt>Configure</rt></ruby>”选项。</p><p>你可能已经安装了一些主题（呃...布局）。从已安装的选项列表中选择它，然后点击右侧的切换按钮。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/change-themes-latte-dock.webp?resize=800%2C393&amp;ssl=1" alt="改变 Latte Dock 的主题"></p><p>你也可以通过点击“<ruby>下载<rt>Download</rt></ruby>”按钮来下载更多的主题。它应该向你显示一个可用的主题列表，以供安装。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/11/08_download_layouts.webp?resize=800%2C450&amp;ssl=1" alt="Latte Dock 插件安装窗口"></p><h4 id="改变停靠区的外观和行为" tabindex="-1">改变停靠区的外观和行为 <a class="header-anchor" href="#改变停靠区的外观和行为" aria-label="Permalink to “改变停靠区的外观和行为”">​</a></h4><p>正如我前面提到的，在 KDE 产品中有大量的定制选项。</p><p>让我们来试试。</p><p>右键点击停靠区，点击 “<ruby>停靠区设置<rt>Dock Settings</rt></ruby>”。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/latte_dock_settings.webp?resize=799%2C246&amp;ssl=1" alt="通过右键点击停靠区进入 Latte Dock 设置"></p><p>在这里，你会得到各种类型的可以切换的选项。想把停靠区移到显示器的左侧吗？你可以通过“<ruby>位置<rt> Location</rt></ruby>”子菜单下提供的选项来实现。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/11_customization_options.webp?resize=800%2C450&amp;ssl=1" alt="Dock 设置和定制窗口"></p><p>如果你觉得可用的选项有任何限制，请拨动右上角的“<ruby>高级<rt>Advanced</rt></ruby>”开关。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/12_customization_options_advanced.webp?resize=800%2C450&amp;ssl=1" alt="现在可以看到带有高级选项的停靠区设置和定制窗口"></p><p>现在看起来真是太棒了！</p><p>试着切换每个可用的开关。你可以延迟隐藏停靠区。你可以把它放在显示器的一个边缘，把它放在该边缘的中心、左边或右边。你可以做到这一切。</p><p>想修饰启动、悬停等效果？在“<ruby>效果<rt>Effects</rt></ruby>”选项卡下有更多的调整选项等待着你。</p><h3 id="从你的系统中删除-latte-dock" tabindex="-1">从你的系统中删除 Latte Dock <a class="header-anchor" href="#从你的系统中删除-latte-dock" aria-label="Permalink to “从你的系统中删除 Latte Dock”">​</a></h3><p>你安装了 Latte Dock，并对其进行了定制，但觉得它不是你想要的东西。而你现在正在寻找删除 Latte Dock 的方法。很好，我帮你。</p><p>你可以使用 <code>apt</code> 软件包管理器删除 Latte Dock。用下面的命令来做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt autoremove --purge latte-dock</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/15_apt_get_remove.webp?resize=800%2C450&amp;ssl=1" alt=""></p><p><code>--purge</code> 标志将删除 Latte Dock 在系统目录中的任何配置文件，除了 <code>~/.config</code>。</p><h4 id="仅供高级用户使用-删除用户特定的遗留文件" tabindex="-1">仅供高级用户使用：删除用户特定的遗留文件 <a class="header-anchor" href="#仅供高级用户使用-删除用户特定的遗留文件" aria-label="Permalink to “仅供高级用户使用：删除用户特定的遗留文件”">​</a></h4>',51)),i("p",null,[t[6]||(t[6]=a("这不是强制性的，但如果你想删除通常放在 ",-1)),t[7]||(t[7]=i("code",null,"$HOME/.config",-1)),t[8]||(t[8]=a("（即 ",-1)),t[9]||(t[9]=i("code",null,"~/.config",-1)),t[10]||(t[10]=a("）目录中的用户配置文件。",-1)),s(e,{href:"https://linuxhandbook.com/find-command-examples/"},{default:o(()=>[...t[5]||(t[5]=[a("使用 find 命令",-1)])]),_:1}),t[11]||(t[11]=a(" 来定位 Latte Dock 的配置文件：",-1))]),t[30]||(t[30]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~/.config -iname &quot;latte*&quot;</span></span></code></pre></div><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/13_find_configs.webp?resize=800%2C450&amp;ssl=1" alt=""></p><p>你可以安全地从你的 <code>~/.config</code> 目录中删除这些目录和配置文件。</p><h4 id="对于-ubuntu-用户-重新启用-ubuntu-停靠区" tabindex="-1">对于 Ubuntu 用户：重新启用 Ubuntu 停靠区 <a class="header-anchor" href="#对于-ubuntu-用户-重新启用-ubuntu-停靠区" aria-label="Permalink to “对于 Ubuntu 用户：重新启用 Ubuntu 停靠区”">​</a></h4><p>不要忘了启用 Ubuntu 的停靠区。如果你不记得了，再次启用停靠区的命令在下面：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gnome-extensions enable ubuntu-dock@ubuntu.com</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>Latte Dock 是一个来自 KDE 社区的令人惊艳的停靠区 ( ͡° ͜ʖ ͡°)</p><p>它提供了大量的主题（布局）、外观和自定义选项，以及一些漂亮的效果。如果你正在考虑定制你的桌面外观和感觉，它肯定是你应该寻找的东西。</p><p>如果你最终喜欢上了 Latte Dock 并开始每天使用它，请在评论中告诉我。如果你不喜欢 Latte Dock，也请发表评论让我知道原因。</p><hr>',11)),i("p",null,[t[13]||(t[13]=a("via: ",-1)),s(e,{href:"https://itsfoss.com/install-use-latte-dock-ubuntu/"},{default:o(()=>[...t[12]||(t[12]=[a("https://itsfoss.com/install-use-latte-dock-ubuntu/",-1)])]),_:1})]),i("p",null,[t[18]||(t[18]=a("作者：",-1)),s(e,{href:"https://itsfoss.com/author/pratham/"},{default:o(()=>[...t[14]||(t[14]=[a("Pratham Patel",-1)])]),_:1}),t[19]||(t[19]=a(" 选题：",-1)),s(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[15]||(t[15]=[a("lujun9972",-1)])]),_:1}),t[20]||(t[20]=a(" 译者：",-1)),s(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[16]||(t[16]=[a("wxy",-1)])]),_:1}),t[21]||(t[21]=a(" 校对：",-1)),s(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[17]||(t[17]=[a("wxy",-1)])]),_:1})]),i("p",null,[t[24]||(t[24]=a("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[22]||(t[22]=[a("LCTT",-1)])]),_:1}),t[25]||(t[25]=a(" 原创编译，",-1)),s(e,{href:"https://linux.cn/"},{default:o(()=>[...t[23]||(t[23]=[a("Linux中国",-1)])]),_:1}),t[26]||(t[26]=a(" 荣誉推出",-1))])])}const y=p(d,[["render",b]]);export{D as __pageData,y as default};
